func (t LintItem) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"rule"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t LintItem) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "ambiguous":
		return t.AsLintAmbiguousItem()
	case "invalid_frontmatter":
		return t.AsLintInvalidFrontmatterItem()
	case "invalid_sources":
		return t.AsLintInvalidSourcesItem()
	case "missing_summary":
		return t.AsLintMissingSummaryItem()
	case "missing_type":
		return t.AsLintMissingTypeItem()
	case "orphans":
		return t.AsLintOrphansItem()
	case "undigested_sources":
		return t.AsLintUndigestedSourcesItem()
	case "wanted":
		return t.AsLintWantedItem()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

